import * as THREE from 'three';
import type { GameContext } from '../../core/GameContext';
import { allSpots } from '../Spots';
import type { WorldUpdatable } from '../World';
import { attachEnvUniforms, ENV_DITHER_GLSL, ENV_NOISE_GLSL, ENV_PARS_GLSL } from './EnvShared';
import { SPECIES, SPECIES_IDS, speciesGeometries, type SpeciesCategory } from './VegetationModels';
import { generateCellBushes, generateCellMain, generateCellSmall, SPECIES_CATEGORY, VEG_CELL, VEG_STRIDE, type VegCellData, type VegCircle } from './VegetationPlacement';

/**
 * Streams instanced vegetation (trees, bushes, rocks, small plants) around the
 * camera, one 64 m cell at a time.
 *
 * - Placement is deterministic (VegetationPlacement) and generated by
 *   resumable jobs within a per-frame time budget.
 * - Every species has near / mid / far LOD meshes. Instances are bucketed per
 *   (species, LOD) into InstancedMeshes; LOD transitions and the far edge use
 *   complementary screen-space dither fades, so there is no popping.
 * - Rendering buffers are rebuilt when the camera moves or turns enough (cells
 *   well outside the view cone are skipped), not every frame.
 * - Tree trunks and big boulders get static colliders while their cell is near
 *   the player, so movement, bending projectiles and raycasts respect them.
 * - `settings.graphics.foliageDensity` applies live (instances store a keep
 *   rank, so thinning never reshuffles the forest).
 */

type LodRanges = [number, number, number];

/** Base LOD switch distances per category: [lod0→1, lod1→2, max]. */
const BASE_RANGES: Record<SpeciesCategory, LodRanges> = {
  tree: [52, 170, 1000],
  bush: [26, 80, 210],
  rock: [36, 110, 420],
  small: [20, 55, 55],
};
const BAND: Record<SpeciesCategory, number> = { tree: 3.5, bush: 2.5, rock: 2.5, small: 2 };
/** Layers per cell: 0 = trees + rocks (far), 1 = bushes, 2 = small plants. Generation radius per layer (beyond the main radius). */
const LAYER_RADIUS = [Infinity, 250, 96];
const LAYERS = 3;
/** Colliders are added for cells closer than this and removed beyond COLLIDER_DROP. */
const COLLIDER_ADD = 110;
const COLLIDER_DROP = 160;

interface CellState {
  key: string;
  cx: number;
  cz: number;
  /** Per layer instance data (null = not generated / unloaded). */
  data: Array<VegCellData | null>;
  mats: Array<Float32Array | null>;
  colliders: number[] | null;
  colliderDensity: number;
}

interface Job {
  key: string;
  layer: number;
  gen: Generator<void, VegCellData, void>;
}

function startJob(layer: number, cx: number, cz: number, ex: readonly VegCircle[]): Generator<void, VegCellData, void> {
  return layer === 0 ? generateCellMain(cx, cz, ex) : layer === 1 ? generateCellBushes(cx, cz, ex) : generateCellSmall(cx, cz, ex);
}

interface Batch {
  species: number;
  lod: number;
  category: SpeciesCategory;
  base: THREE.BufferGeometry;
  mesh: THREE.InstancedMesh | null;
  geo: THREE.BufferGeometry | null;
  tint: THREE.InstancedBufferAttribute | null;
  capacity: number;
  count: number;
  material: THREE.MeshLambertMaterial;
  fade: THREE.Vector4;
}

const VEG_VERT_PARS = /* glsl */ `
attribute vec2 veg;
attribute vec4 aTint;
uniform vec4 uFade;
uniform float uFlex;
uniform float uPush;
uniform vec2 uCrown;
varying float vFadeIn;
varying float vFadeOut;
varying float vLeaf;
varying float vSeeThrough;
${ENV_PARS_GLSL}
${ENV_NOISE_GLSL}
`;

const VEG_PROJECT = /* glsl */ `
vec4 mvPosition = vec4( transformed, 1.0 );
vec3 instPos = vec3( 0.0 );
#ifdef USE_INSTANCING
  mvPosition = instanceMatrix * mvPosition;
  instPos = instanceMatrix[ 3 ].xyz;
#endif
float vegW = veg.x;
vLeaf = veg.y;
if ( vegW > 0.0 ) {
  float phase = envHash( instPos.xz * 0.37 ) * 6.2831;
  mvPosition.xyz += envWindSway( instPos, uFlex * vegW, phase );
  if ( uPush > 0.0 ) {
    vec2 push = envInteractPush( mvPosition.xyz );
    float pl = min( length( push ), 1.4 );
    mvPosition.xz += push * uPush * vegW * 0.9;
    mvPosition.y -= pl * uPush * vegW * 0.35;
  }
}
float camD = length( instPos.xz - cameraPosition.xz );
// Camera inside a crown (third-person camera pushed into a tree): thin the whole plant out.
#ifdef USE_INSTANCING
  float instScale = length( instanceMatrix[ 0 ].xyz );
#else
  float instScale = 1.0;
#endif
float inside = 1.0 - smoothstep( uCrown.x * instScale * 0.8, uCrown.x * instScale * 1.25 + 0.5, camD );
inside *= step( instPos.y - 1.0, cameraPosition.y ) * step( cameraPosition.y, instPos.y + uCrown.y * instScale + 1.5 );
// Fully gone while the camera is inside it (a partial screen-door reads as noise).
vSeeThrough = 1.0 - inside;
vFadeIn = clamp( ( camD - uFade.x ) / max( uFade.y - uFade.x, 1e-3 ), 0.0, 1.0 );
vFadeOut = 1.0 - clamp( ( camD - uFade.z ) / max( uFade.w - uFade.z, 1e-3 ), 0.0, 1.0 );
mvPosition = modelViewMatrix * mvPosition;
gl_Position = projectionMatrix * mvPosition;
`;

function createVegMaterial(flex: number, push: number, crown: THREE.Vector2): THREE.MeshLambertMaterial {
  const mat = new THREE.MeshLambertMaterial({ vertexColors: true });
  const fade = new THREE.Vector4(-2, -1, 1e6, 1e6 + 1);
  mat.userData.fade = fade;
  mat.onBeforeCompile = (shader) => {
    attachEnvUniforms(shader);
    shader.uniforms.uFade = { value: fade };
    shader.uniforms.uFlex = { value: flex };
    shader.uniforms.uPush = { value: push };
    shader.uniforms.uCrown = { value: crown };
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\n' + VEG_VERT_PARS)
      .replace('#include <color_vertex>', '#include <color_vertex>\n  vColor.rgb *= mix( vec3( 1.0 ), aTint.rgb, veg.y );')
      .replace('#include <project_vertex>', VEG_PROJECT);
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', '#include <common>\nvarying float vFadeIn;\nvarying float vFadeOut;\nvarying float vLeaf;\nvarying float vSeeThrough;\nuniform vec3 uSkyHorizon;\nuniform vec3 uSunColor;\nuniform float uDaylight;\n' + ENV_DITHER_GLSL)
      // Foliage scatters light: lift shadowed leaves with sky fill and a little sun translucency.
      .replace('#include <opaque_fragment>', '  outgoingLight += diffuseColor.rgb * vLeaf * ( uSkyHorizon * 0.16 + uSunColor * 0.12 * uDaylight );\n#include <opaque_fragment>')
      .replace(
        '#include <clipping_planes_fragment>',
        `#include <clipping_planes_fragment>
  float vegDither = envDither( gl_FragCoord.xy );
  if ( vFadeIn < 1.0 && vFadeIn <= 1.0 - vegDither ) discard;
  if ( vFadeOut < 1.0 && vFadeOut <= vegDither ) discard;
  if ( vSeeThrough < 1.0 && vSeeThrough <= vegDither ) discard;
  // Never fill the screen with a leaf right in front of the lens: plants between
  // the third-person camera and the player dissolve (dithered) as they get close.
  float vegNear = smoothstep( 1.1, 2.3, length( vViewPosition ) );
  if ( vegNear < 1.0 && vegNear <= vegDither ) discard;`,
      );
  };
  mat.customProgramCacheKey = () => 'veg-v5';
  return mat;
}

function cellKey(cx: number, cz: number): string {
  return cx + ',' + cz;
}

/** Column-major instance matrices (yaw + scale + translation) for a cell's instances. */
function buildMatrices(d: VegCellData): Float32Array {
  const m = new Float32Array(d.count * 16);
  const a = d.data;
  for (let i = 0; i < d.count; i++) {
    const o = i * VEG_STRIDE, q = i * 16;
    const yaw = a[o + 3], sxz = a[o + 4], sy = a[o + 5];
    const c = Math.cos(yaw), s = Math.sin(yaw);
    m[q] = c * sxz; m[q + 1] = 0; m[q + 2] = -s * sxz; m[q + 3] = 0;
    m[q + 4] = 0; m[q + 5] = sy; m[q + 6] = 0; m[q + 7] = 0;
    m[q + 8] = s * sxz; m[q + 9] = 0; m[q + 10] = c * sxz; m[q + 11] = 0;
    m[q + 12] = a[o]; m[q + 13] = a[o + 1]; m[q + 14] = a[o + 2]; m[q + 15] = 1;
  }
  return m;
}

export class VegetationSystem implements WorldUpdatable {
  readonly group = new THREE.Group();
  private readonly cells = new Map<string, CellState>();
  private readonly jobs = new Map<string, Job>();
  private readonly batches: Batch[][] = [];
  private density = 1;
  private lodScale = 1;
  private shadows = true;
  private shadowReach = 45;
  private drawDistance = 750;
  private dirty = true;
  private readonly lastCam = new THREE.Vector3(1e9, 0, 0);
  private lastYaw = 0;
  private rebuildTimer = 0;
  private exclusions: VegCircle[] = [];
  private spotCount = -1;
  private readonly fwd = new THREE.Vector3();
  /** Instances drawn in the last rebuild (stats / tests). */
  drawn = 0;
  enabled = true;

  constructor(private readonly ctx: GameContext) {
    this.group.name = 'vegetation';
    ctx.world.group.add(this.group);
    this.applySettings();
    ctx.events.on('settings:changed', () => this.applySettings());
  }

  /**
   * Species models and materials are built lazily (first preload / update) so
   * they never weigh on page boot; the loading screen absorbs the cost.
   */
  private ensureBatches(): void {
    if (this.batches.length) return;
    const geos = speciesGeometries();
    SPECIES_IDS.forEach((id, si) => {
      const lods = geos.get(id)!;
      const def = SPECIES[id];
      const row: Batch[] = [];
      for (let l = 0; l < 3; l++) {
        const base = lods[l];
        if (!base) continue;
        lods[0].computeBoundingBox();
        const bb = lods[0].boundingBox!;
        const crown = new THREE.Vector2(Math.max(-bb.min.x, bb.max.x, -bb.min.z, bb.max.z), bb.max.y);
        const material = createVegMaterial(def.flex * (l === 2 ? 0.6 : 1), def.push, crown);
        row.push({ species: si, lod: l, category: def.category, base, mesh: null, geo: null, tint: null, capacity: 0, count: 0, material, fade: material.userData.fade as THREE.Vector4 });
      }
      this.batches.push(row);
    });
    this.updateFadeUniforms();
    this.dirty = true;
  }

  private applySettings(): void {
    const g = this.ctx.settings.data.graphics;
    const density = Math.max(0, Math.min(1.5, g.foliageDensity));
    if (density !== this.density) {
      this.density = density;
      for (const c of this.cells.values()) this.syncColliders(c, true);
    }
    this.lodScale = 1 / (1 + g.lodBias);
    this.shadows = g.shadows !== 'off';
    this.shadowReach = g.shadows === 'high' ? 95 : g.shadows === 'medium' ? 70 : g.shadows === 'low' ? 45 : 0;
    this.drawDistance = g.drawDistance;
    this.updateFadeUniforms();
    this.dirty = true;
  }

  /** Near LOD always casts; the mid LOD only when the shadow map reaches beyond the near range. */
  private castsShadow(b: Batch): boolean {
    if (!this.shadows || !SPECIES[SPECIES_IDS[b.species]].shadow) return false;
    return b.lod === 0 || (b.lod === 1 && this.shadowReach > this.ranges(b.category)[0]);
  }

  private ranges(cat: SpeciesCategory): LodRanges {
    const r = BASE_RANGES[cat];
    const q = this.lodScale;
    const max = Math.min(r[2], this.drawDistance * (cat === 'tree' ? 0.98 : 1));
    return [r[0] * q, Math.min(r[1] * q, max), cat === 'small' ? r[2] * q : max];
  }

  private updateFadeUniforms(): void {
    for (const row of this.batches) {
      const hasL2 = row.length === 3;
      for (const b of row) {
        const [r0, r1, rmax] = this.ranges(b.category);
        const band = BAND[b.category];
        const f = b.fade;
        if (b.lod === 0) f.set(-2, -1, r0 - band, r0 + band);
        else if (b.lod === 1) {
          if (hasL2) f.set(r0 - band, r0 + band, r1 - band, r1 + band);
          else f.set(r0 - band, r0 + band, rmax - band * 3, rmax);
        } else f.set(r1 - band, r1 + band, rmax - band * 4, rmax);
        if (b.mesh) b.mesh.castShadow = this.castsShadow(b);
      }
    }
  }

  // ---------------------------------------------------------------------------
  // Streaming
  // ---------------------------------------------------------------------------

  private refreshExclusions(): void {
    const spots = allSpots();
    if (spots.length === this.spotCount) return;
    this.spotCount = spots.length;
    const next: VegCircle[] = [];
    for (const [, s] of spots) if (s.r && s.r > 0) next.push({ x: s.x, z: s.z, r: s.r + 2 });
    // Regenerate cells that a newly defined clearing overlaps.
    for (const c of next) {
      if (this.exclusions.some((e) => e.x === c.x && e.z === c.z && e.r === c.r)) continue;
      for (const cell of this.cells.values()) {
        const mx = (cell.cx + 0.5) * VEG_CELL, mz = (cell.cz + 0.5) * VEG_CELL;
        if (Math.hypot(mx - c.x, mz - c.z) < c.r + VEG_CELL) this.dropCell(cell);
      }
    }
    this.exclusions = next;
  }

  private dropCell(cell: CellState): void {
    this.removeColliders(cell);
    this.cells.delete(cell.key);
    for (let l = 0; l < LAYERS; l++) this.jobs.delete(cell.key + ':' + l);
    this.dirty = true;
  }

  private mainRadius(): number {
    return Math.min(BASE_RANGES.tree[2], this.drawDistance) + VEG_CELL * 0.75;
  }

  /** Create missing cells / jobs around p, run jobs for up to budgetMs. Returns pending job count. */
  private stream(p: THREE.Vector3, budgetMs: number): number {
    this.refreshExclusions();
    const R = this.mainRadius();
    const c0x = Math.floor((p.x - R) / VEG_CELL), c1x = Math.floor((p.x + R) / VEG_CELL);
    const c0z = Math.floor((p.z - R) / VEG_CELL), c1z = Math.floor((p.z + R) / VEG_CELL);
    const want: Array<{ key: string; cx: number; cz: number; d: number; layer: number }> = [];
    for (let cz = c0z; cz <= c1z; cz++) {
      for (let cx = c0x; cx <= c1x; cx++) {
        const mx = (cx + 0.5) * VEG_CELL, mz = (cz + 0.5) * VEG_CELL;
        const d = Math.max(0, Math.hypot(mx - p.x, mz - p.z) - VEG_CELL * 0.71);
        if (d > R) continue;
        const key = cellKey(cx, cz);
        let cell = this.cells.get(key);
        if (!cell) {
          cell = { key, cx, cz, data: [null, null, null], mats: [null, null, null], colliders: null, colliderDensity: -1 };
          this.cells.set(key, cell);
        }
        for (let l = 0; l < LAYERS; l++) {
          if (!cell.data[l] && d < LAYER_RADIUS[l]) want.push({ key, cx, cz, d: d + l * 30, layer: l });
        }
      }
    }
    // Evict far cells.
    const evictR = R + VEG_CELL * 2;
    for (const cell of [...this.cells.values()]) {
      const mx = (cell.cx + 0.5) * VEG_CELL, mz = (cell.cz + 0.5) * VEG_CELL;
      const d = Math.hypot(mx - p.x, mz - p.z);
      if (d > evictR) {
        this.dropCell(cell);
        continue;
      }
      for (let l = 1; l < LAYERS; l++) {
        if (cell.data[l] && d > LAYER_RADIUS[l] + VEG_CELL * 2) {
          cell.data[l] = null;
          cell.mats[l] = null;
          this.dirty = true;
        }
      }
    }
    if (!want.length) return 0;
    want.sort((a, b) => a.d - b.d);
    const t0 = performance.now();
    let done = 0;
    for (const w of want) {
      if (performance.now() - t0 > budgetMs) break;
      const jk = w.key + ':' + w.layer;
      let job = this.jobs.get(jk);
      if (!job) {
        job = { key: w.key, layer: w.layer, gen: startJob(w.layer, w.cx, w.cz, this.exclusions) };
        this.jobs.set(jk, job);
      }
      let r = job.gen.next();
      while (!r.done && performance.now() - t0 <= budgetMs) r = job.gen.next();
      if (!r.done) break;
      this.jobs.delete(jk);
      const cell = this.cells.get(w.key);
      if (!cell) continue;
      cell.data[w.layer] = r.value;
      cell.mats[w.layer] = buildMatrices(r.value);
      done++;
      this.dirty = true;
    }
    return Math.max(0, want.length - done);
  }

  // ---------------------------------------------------------------------------
  // Colliders
  // ---------------------------------------------------------------------------

  private removeColliders(cell: CellState): void {
    if (!cell.colliders) return;
    for (const id of cell.colliders) this.ctx.world.collision.remove(id);
    cell.colliders = null;
    cell.colliderDensity = -1;
  }

  private syncColliders(cell: CellState, force = false): void {
    const d = cell.data[0];
    if (!d) return;
    if (cell.colliders && !force && cell.colliderDensity === this.density) return;
    this.removeColliders(cell);
    const ids: number[] = [];
    const a = d.data;
    const rockIdx = SPECIES_IDS.indexOf('rock');
    for (let i = 0; i < d.count; i++) {
      const o = i * VEG_STRIDE;
      if (a[o + 9] >= this.density) continue;
      const sp = d.species[i];
      const def = SPECIES[SPECIES_IDS[sp]];
      const x = a[o], y = a[o + 1], z = a[o + 2], sxz = a[o + 4], sy = a[o + 5];
      if (def.category === 'tree' && def.trunkR > 0) {
        const r = def.trunkR * sxz;
        const hy = def.height * sy * 0.45;
        ids.push(this.ctx.world.collision.add({ shape: 'cylinder', x, y: y + hy, z, r, hy, solid: true, walkable: false, surface: 'wood', tag: 'vegetation' }));
      } else if (sp === rockIdx && sxz >= 1.15) {
        // Boulder: walkable top a little below the rounded crest.
        const top = 0.82 * sy;
        const hy = (top + 0.6) / 2;
        ids.push(this.ctx.world.collision.add({ shape: 'cylinder', x, y: y + top - hy, z, r: 0.78 * sxz, hy, solid: true, walkable: true, surface: 'rock', tag: 'vegetation' }));
      }
    }
    cell.colliders = ids;
    cell.colliderDensity = this.density;
  }

  private updateColliders(p: THREE.Vector3): void {
    for (const cell of this.cells.values()) {
      const mx = (cell.cx + 0.5) * VEG_CELL, mz = (cell.cz + 0.5) * VEG_CELL;
      const d = Math.hypot(mx - p.x, mz - p.z);
      if (d < COLLIDER_ADD) this.syncColliders(cell);
      else if (d > COLLIDER_DROP) this.removeColliders(cell);
    }
  }

  // ---------------------------------------------------------------------------
  // Instance buffers
  // ---------------------------------------------------------------------------

  private ensureCapacity(b: Batch, n: number): void {
    if (n <= b.capacity && b.mesh) return;
    const cap = Math.max(64, Math.ceil(Math.max(n, b.capacity * 1.6) / 64) * 64);
    if (b.mesh) {
      this.group.remove(b.mesh);
      b.mesh.dispose();
      b.geo?.dispose();
    }
    const geo = b.base.clone();
    const tint = new THREE.InstancedBufferAttribute(new Float32Array(cap * 4), 4);
    tint.setUsage(THREE.DynamicDrawUsage);
    geo.setAttribute('aTint', tint);
    const mesh = new THREE.InstancedMesh(geo, b.material, cap);
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    mesh.frustumCulled = false;
    mesh.matrixAutoUpdate = false;
    mesh.receiveShadow = true;
    mesh.castShadow = this.castsShadow(b);
    mesh.name = `veg_${SPECIES_IDS[b.species]}_${b.lod}`;
    mesh.count = 0;
    this.group.add(mesh);
    b.mesh = mesh;
    b.geo = geo;
    b.tint = tint;
    b.capacity = cap;
  }

  private rebuild(cam: THREE.Vector3): void {
    this.dirty = false;
    const camObj = this.ctx.camera;
    camObj.getWorldDirection(this.fwd);
    const fl = Math.hypot(this.fwd.x, this.fwd.z) || 1;
    const fx = this.fwd.x / fl, fz = this.fwd.z / fl;
    const aspect = (camObj as THREE.PerspectiveCamera).aspect ?? 1.7;
    const vfov = ((camObj as THREE.PerspectiveCamera).fov ?? 60) * (Math.PI / 180);
    const halfH = Math.atan(Math.tan(vfov / 2) * aspect);
    // Generous cone: the buffers are only rebuilt every few degrees of turning.
    const cone = Math.min(Math.PI, halfH + 0.55);
    // Looking steeply down/up: never cull by direction.
    const steep = Math.abs(this.fwd.y) > 0.8;
    for (const row of this.batches) for (const b of row) b.count = 0;
    // Pass 1: count per batch so capacities are known before writing.
    const R: LodRanges[] = [];
    for (const cat of ['tree', 'bush', 'rock', 'small'] as SpeciesCategory[]) R.push(this.ranges(cat));
    const catIdx: Record<SpeciesCategory, number> = { tree: 0, bush: 1, rock: 2, small: 3 };
    const visible: CellState[] = [];
    const maxR = Math.max(R[0][2], R[2][2]);
    for (const cell of this.cells.values()) {
      if (!cell.data[0] && !cell.data[1] && !cell.data[2]) continue;
      const mx = (cell.cx + 0.5) * VEG_CELL - cam.x, mz = (cell.cz + 0.5) * VEG_CELL - cam.z;
      const dist = Math.hypot(mx, mz);
      if (dist - VEG_CELL * 0.71 > maxR) continue;
      if (!steep && dist > VEG_CELL) {
        const ang = Math.acos(Math.max(-1, Math.min(1, (mx * fx + mz * fz) / dist)));
        if (ang - Math.asin(Math.min(1, (VEG_CELL * 0.75) / dist)) > cone) continue;
      }
      visible.push(cell);
    }
    const density = this.density;
    const pass = (write: boolean): void => {
      for (const cell of visible) {
        for (let part = 0; part < LAYERS; part++) {
          const d = cell.data[part];
          const mats = cell.mats[part];
          if (!d || !mats) continue;
          const a = d.data;
          for (let i = 0; i < d.count; i++) {
            const o = i * VEG_STRIDE;
            if (a[o + 9] >= density) continue;
            const sp = d.species[i];
            const cat = SPECIES_CATEGORY[sp];
            const rr = R[catIdx[cat]];
            const dx = a[o] - cam.x, dz = a[o + 2] - cam.z;
            const dist = Math.sqrt(dx * dx + dz * dz);
            if (dist > rr[2]) continue;
            // Far thinning: beyond ~1.6x the mid-LOD range keep a shrinking share of the
            // instances (by keep rank, so it is stable); fog hides the difference.
            const thin0 = rr[1] * 1.6;
            if (dist > thin0 && a[o + 9] >= density * (1 - 0.55 * Math.min(1, (dist - thin0) / (thin0 * 0.8)))) continue;
            const band = BAND[cat];
            const row = this.batches[sp];
            const hasL2 = row.length === 3;
            if (dist < rr[0] + band) this.put(row[0], mats, i, a, o, write);
            if (dist > rr[0] - band && (dist < rr[1] + band || !hasL2)) this.put(row[1], mats, i, a, o, write);
            if (hasL2 && dist > rr[1] - band) this.put(row[2], mats, i, a, o, write);
          }
        }
      }
    };
    pass(false);
    let total = 0;
    for (const row of this.batches) {
      for (const b of row) {
        if (b.count > 0) this.ensureCapacity(b, b.count);
        total += b.count;
        b.count = 0;
      }
    }
    pass(true);
    for (const row of this.batches) {
      for (const b of row) {
        if (!b.mesh) continue;
        b.mesh.count = b.count;
        if (b.count > 0) {
          const im = b.mesh.instanceMatrix;
          im.clearUpdateRanges();
          im.addUpdateRange(0, b.count * 16);
          im.needsUpdate = true;
          const t = b.tint!;
          t.clearUpdateRanges();
          t.addUpdateRange(0, b.count * 4);
          t.needsUpdate = true;
        }
      }
    }
    this.drawn = total;
  }

  private put(b: Batch, mats: Float32Array, i: number, a: Float32Array, o: number, write: boolean): void {
    const n = b.count++;
    if (!write) return;
    const dst = b.mesh!.instanceMatrix.array as Float32Array;
    const q = n * 16, s = i * 16;
    for (let k = 0; k < 16; k++) dst[q + k] = mats[s + k];
    const t = b.tint!.array as Float32Array;
    t[n * 4] = a[o + 6];
    t[n * 4 + 1] = a[o + 7];
    t[n * 4 + 2] = a[o + 8];
    t[n * 4 + 3] = 1;
  }

  // ---------------------------------------------------------------------------
  // WorldUpdatable
  // ---------------------------------------------------------------------------

  update(dt: number, ctx: GameContext, focus: THREE.Vector3): void {
    this.ensureBatches();
    if (!this.enabled) {
      this.group.visible = false;
      return;
    }
    this.group.visible = true;
    const cam = ctx.camera.position;
    // Stream around the player, but keep the camera's surroundings filled too.
    const pending = this.stream(focus, 1.6);
    this.updateColliders(focus);
    this.rebuildTimer -= dt;
    ctx.camera.getWorldDirection(this.fwd);
    const yaw = Math.atan2(this.fwd.x, this.fwd.z);
    let dy = Math.abs(yaw - this.lastYaw);
    if (dy > Math.PI) dy = Math.PI * 2 - dy;
    const moved = cam.distanceToSquared(this.lastCam);
    if (this.dirty || moved > 16 || dy > 0.3 || this.rebuildTimer <= 0 || (pending > 0 && this.rebuildTimer < 0.75)) {
      this.lastCam.copy(cam);
      this.lastYaw = yaw;
      this.rebuildTimer = 1.5;
      this.rebuild(cam);
    }
  }

  preload(p: THREE.Vector3, budgetMs: number): number {
    this.ensureBatches();
    if (!this.enabled) return 0;
    const pending = this.stream(p, budgetMs);
    if (pending === 0) {
      this.updateColliders(p);
      this.dirty = true;
    }
    return pending;
  }

  /** Stats for tests / debugging. */
  stats(): { cells: number; instances: number; drawn: number; colliders: number; jobs: number } {
    let inst = 0, cols = 0;
    for (const c of this.cells.values()) {
      for (const d of c.data) inst += d?.count ?? 0;
      cols += c.colliders?.length ?? 0;
    }
    return { cells: this.cells.size, instances: inst, drawn: this.drawn, colliders: cols, jobs: this.jobs.size };
  }

  /** Visible (density-kept) instances within radius r of (x,z): species ids and positions. */
  query(x: number, z: number, r: number): Array<{ species: string; x: number; y: number; z: number; scale: number }> {
    const out: Array<{ species: string; x: number; y: number; z: number; scale: number }> = [];
    for (const c of this.cells.values()) {
      for (const d of c.data) {
        if (!d) continue;
        for (let i = 0; i < d.count; i++) {
          const o = i * VEG_STRIDE;
          if (d.data[o + 9] >= this.density) continue;
          if (Math.hypot(d.data[o] - x, d.data[o + 2] - z) > r) continue;
          out.push({ species: SPECIES_IDS[d.species[i]], x: d.data[o], y: d.data[o + 1], z: d.data[o + 2], scale: d.data[o + 4] });
        }
      }
    }
    return out;
  }

  dispose(): void {
    for (const c of this.cells.values()) this.removeColliders(c);
    this.cells.clear();
    this.jobs.clear();
    for (const row of this.batches) {
      for (const b of row) {
        if (b.mesh) {
          this.group.remove(b.mesh);
          b.mesh.dispose();
        }
        b.geo?.dispose();
        b.material.dispose();
        b.mesh = null;
        b.geo = null;
      }
    }
    this.group.removeFromParent();
  }
}
